//! Minimum viable income — the smallest monthly income that holds, in TIERS, on the WORST month.
//!
//! "How much do I need to earn?" has no single answer, and pretending it does is what makes the
//! answer useless. Needing $2,100 to keep the lights on and $4,300 to stop the debt growing are both
//! true and they lead to completely different decisions. So this reports a ladder:
//!
//! - **Survival** — what cannot lapse: housing, utilities, insurance, healthcare, debt minimums, and
//!   the groceries and transport that get you to work. Everything else is given up, and the list of
//!   what you gave up is part of the answer.
//! - **Current** — survival plus every standing obligation, so nothing goes delinquent. This is the
//!   headline: it is the line below which NEW damage starts.
//! - **Stable** — current plus ordinary discretionary spending, so nothing is drawn from savings.
//! - **Progress** — stable plus a deliberate payment above the minimums.
//!
//! # The headline is the worst month, not the average
//!
//! The same discipline the runway uses. An annual insurance renewal makes one month cost $900 more
//! than the other eleven; an income that covers the median clears every month except the one it does
//! not, and that month is a missed payment. The median is reported too, because THE GAP BETWEEN THE
//! TWO IS THE SAVING-UP PROBLEM.
use crate::money::{money, Currency, Money};
use crate::obligations::{months_between, ObligationCalendar};
use crate::projection::IncomeProjection;
use crate::spending::SpendingAnalysis;
use crate::txn::month_of;

pub(crate) use is_essential_category::is_essential_category;
pub(crate) use median::median;
pub(crate) use obligation_is_essential::obligation_is_essential;
pub use cleared_tiers::cleared_tiers;
pub use summarise_viable::summarise_viable;
pub use ladder_is_ordered::ladder_is_ordered;
pub use over_window::over_window;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Tier {
    Survival,
    Current,
    Stable,
    Progress,
}

impl Tier {
    pub fn label(self) -> &'static str {
        match self {
            Tier::Survival => "survival",
            Tier::Current => "current",
            Tier::Stable => "stable",
            Tier::Progress => "progress",
        }
    }
}

/// What cannot be given up without losing something that costs more than it saves — a home, a car
/// that gets you to work, cover against a bill that would end this. DATA, so it can be argued with.
pub const ESSENTIAL_CATEGORIES: &[&str] = &["housing", "utilities", "insurance", "healthcare", "childcare", "groceries", "transport", "fuel"];

#[derive(Debug, Clone, PartialEq)]
pub struct TierRequirement {
    pub tier: Tier,
    /// The usual month. What the ladder looks like most of the time.
    pub typical_month: Money,
    /// The month that costs MOST. This is what an income has to clear.
    pub worst_month: Money,
    pub worst_month_name: String,
    /// In this tier's words, what it buys.
    pub includes: Vec<String>,
    /// What is given up at this tier, so the trade is VISIBLE rather than implied.
    pub excludes: Vec<String>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct TierGap {
    pub tier: Tier,
    /// POSITIVE shortfall against the LOW income band in the worst month. Zero when already clear.
    pub shortfall: Money,
    pub clears: bool,
}

#[derive(Debug, Clone, PartialEq)]
pub struct ViableIncome {
    pub currency: Currency,
    pub from: String,
    pub to: String,
    pub tiers: Vec<TierRequirement>,
    /// The absolute floor: what cannot lapse.
    pub floor: TierRequirement,
    /// The line below which NEW damage starts — the number to quote when asked one.
    pub headline: TierRequirement,
    /// Against the projection's LOW band, tier by tier. ABSENT when there is no projection to
    /// compare against — not a row of zeroes, which would read as "you clear everything".
    pub gaps: Option<Vec<TierGap>>,
    pub notes: Vec<String>,
}

pub struct ViableOptions {
    /// A deliberate payment above the minimums — what turns holding on into getting out.
    pub progress_target: Money,
}

pub fn minimum_viable_income(
    calendar: &ObligationCalendar,
    spending: &SpendingAnalysis,
    currency: Currency,
    projection: Option<&IncomeProjection>,
    opts: &ViableOptions,
) -> ViableIncome {
    let mut notes: Vec<String> = Vec::new();
    let months = months_between(&calendar.from, &calendar.to);

    let mut unplaced: Vec<String> = Vec::new();
    let mut essential_by_month: Vec<(String, i64)> = months.iter().map(|m| (m.clone(), 0)).collect();
    let mut all_by_month: Vec<(String, i64)> = months.iter().map(|m| (m.clone(), 0)).collect();
    for o in &calendar.obligations {
        let m = &o.date[..7.min(o.date.len())];
        let Some(slot) = all_by_month.iter_mut().find(|(k, _)| k == m) else { continue };
        slot.1 += o.amount.minor;
        let (essential, placed) = obligation_is_essential(&o.label, o.kind);
        if !placed && !unplaced.contains(&o.label) {
            unplaced.push(o.label.clone());
        }
        if essential {
            if let Some(e) = essential_by_month.iter_mut().find(|(k, _)| k == m) {
                e.1 += o.amount.minor;
            }
        }
    }
    if !unplaced.is_empty() {
        notes.push(format!(
            "{} obligation(s) matched no category and are counted as ESSENTIAL — for a floor, over-stating costs you a bigger target and under-stating costs you a missed payment: {}",
            unplaced.len(),
            unplaced.join(", ")
        ));
    }

    // VARIABLE SPENDING IS SUMMED FROM THE SAME PARTS ON BOTH SIDES, deliberately. Medians do not
    // add, so `spending.variable_monthly` (a median of totals) and the sum of per-category medians
    // are different numbers — and mixing the two would let the essential half exceed the whole,
    // which would put the ladder out of order for reasons nobody could see in the output.
    // VARIABLE CATEGORIES ONLY. `categories` covers every outflow that was spent, fixed charges
    // included — so rent appears BOTH there and on the obligation calendar, and summing the two
    // counted it twice. Every tier came out overstated by the whole of the rent, which tells
    // somebody they need to earn far more than they do. Found by running the binary, not by tests.
    let essential_variable: i64 = spending.variable_categories.iter().filter(|c| is_essential_category(c.category)).map(|c| c.typical_month.minor).sum();
    let categorised_variable: i64 = spending.variable_categories.iter().map(|c| c.typical_month.minor).sum();

    let mut uncat_by_month: Vec<(String, i64)> = Vec::new();
    for t in &spending.uncategorised {
        let m = month_of(&t.date).to_string();
        match uncat_by_month.iter_mut().find(|(k, _)| *k == m) {
            Some((_, v)) => *v += -t.amount.minor,
            None => uncat_by_month.push((m, -t.amount.minor)),
        }
    }
    let uncategorised_variable = median(&uncat_by_month.iter().map(|(_, v)| *v).collect::<Vec<_>>());
    let all_variable = categorised_variable + uncategorised_variable;

    if all_variable != spending.variable_monthly.minor {
        notes.push(format!(
            "variable spending here is {} minor units, against {} reported by the spending analysis — medians do not add, and this figure is built from the same parts as the essential half so the ladder cannot come out of order",
            all_variable, spending.variable_monthly.minor
        ));
    }

    let build = |tier: Tier, per: &dyn Fn(&str) -> i64, includes: Vec<String>, excludes: Vec<String>| -> TierRequirement {
        let totals: Vec<i64> = months.iter().map(|m| per(m)).collect();
        // The FIRST maximum wins on a tie — strictly greater, so the earliest month is named and a
        // reader is pointed at the one arriving soonest.
        let mut worst_at = 0usize;
        for i in 1..totals.len() {
            if totals[i] > totals[worst_at] {
                worst_at = i;
            }
        }
        TierRequirement {
            tier,
            typical_month: money(median(&totals), currency),
            worst_month: money(totals.get(worst_at).copied().unwrap_or(0), currency),
            worst_month_name: months.get(worst_at).cloned().unwrap_or_else(|| calendar.from[..7.min(calendar.from.len())].to_string()),
            includes,
            excludes,
        }
    };

    let ess = |m: &str| essential_by_month.iter().find(|(k, _)| k == m).map(|(_, v)| *v).unwrap_or(0);
    let all = |m: &str| all_by_month.iter().find(|(k, _)| k == m).map(|(_, v)| *v).unwrap_or(0);
    let s = |v: &[&str]| v.iter().map(|x| x.to_string()).collect::<Vec<String>>();

    let survival = build(
        Tier::Survival,
        &|m| ess(m) + essential_variable,
        s(&["housing, utilities, insurance, healthcare and childcare", "every debt MINIMUM — a missed one is a credit event", "groceries, transport and fuel"]),
        s(&["every subscription and membership", "dining, entertainment and shopping", "anything paid above a minimum"]),
    );
    let current = build(
        Tier::Current,
        &|m| all(m) + essential_variable,
        s(&["everything in survival", "every standing obligation, so nothing goes delinquent"]),
        s(&["dining, entertainment and shopping", "anything paid above a minimum"]),
    );
    let stable = build(
        Tier::Stable,
        &|m| all(m) + all_variable,
        s(&["everything in current", "ordinary discretionary spending, so nothing is drawn from savings"]),
        s(&["anything paid above a minimum — the debt stops growing but does not shrink"]),
    );
    let progress = build(
        Tier::Progress,
        &|m| all(m) + all_variable + opts.progress_target.minor,
        vec!["everything in stable".to_string(), format!("a deliberate {} minor units a month above the minimums", opts.progress_target.minor)],
        Vec::new(),
    );

    if opts.progress_target.minor == 0 {
        notes.push("no progress target was given, so PROGRESS equals STABLE — a stable position is one where the debt stops growing, not one where it shrinks".to_string());
    }
    let spread = current.worst_month.minor - current.typical_month.minor;
    if spread > 0 {
        notes.push(format!(
            "{} costs {} minor units more than the usual month — an income that only clears the median misses that month, and the gap between the two is the amount to have put aside before it arrives",
            current.worst_month_name, spread
        ));
    }

    let tiers = vec![survival.clone(), current.clone(), stable, progress];
    let gaps = match projection {
        Some(p) if p.projectable => Some(
            tiers
                .iter()
                .map(|t| {
                    let band = p.months.iter().find(|b| b.month == t.worst_month_name).or_else(|| p.months.first());
                    let income = band.map(|b| b.low.minor).unwrap_or(0);
                    let short = (t.worst_month.minor - income).max(0);
                    TierGap { tier: t.tier, shortfall: money(short, currency), clears: short == 0 }
                })
                .collect(),
        ),
        _ => None,
    };

    ViableIncome {
        currency,
        from: calendar.from.clone(),
        to: calendar.to.clone(),
        floor: survival,
        // CURRENT is the headline. Survival means letting things lapse, which has consequences that
        // outlast the month it saved; current is the line below which NEW damage starts.
        headline: current,
        tiers,
        gaps,
        notes,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::obligations::ObligationKind;
    use crate::money::usd;
    use crate::obligations::{Confidence, Obligation};
    use crate::projection::{MonthBand, ProjectionTotal};
    use crate::spending::CategoryTotal;
    use crate::txn::Txn;

    // SYNTHETIC FIXTURES ONLY.
    fn ob(date: &str, label: &str, minor: i64, kind: ObligationKind) -> Obligation {
        Obligation {
            date: date.to_string(),
            label: label.to_string(),
            account: "chk".to_string(),
            amount: usd(minor),
            kind,
            confidence: Confidence::Observed,
            regularity: None,
        }
    }

    fn calendar() -> ObligationCalendar {
        ObligationCalendar {
            from: "2026-07-01".to_string(),
            to: "2026-09-30".to_string(),
            by_month: Vec::new(),
            heaviest: None,
            notes: Vec::new(),
            obligations: vec![
                ob("2026-07-05", "RENT LANDLORD LLC", 120_000, ObligationKind::Recurring),
                ob("2026-07-12", "NETFLIX.COM", 1_599, ObligationKind::Recurring),
                ob("2026-07-20", "CITY POWER 0412", 9_000, ObligationKind::Recurring),
                ob("2026-07-01", "chase minimum", 6_000, ObligationKind::Minimum),
                ob("2026-08-05", "RENT LANDLORD LLC", 120_000, ObligationKind::Recurring),
                ob("2026-08-12", "NETFLIX.COM", 1_599, ObligationKind::Recurring),
                ob("2026-08-20", "CITY POWER 0412", 9_000, ObligationKind::Recurring),
                ob("2026-08-01", "chase minimum", 6_000, ObligationKind::Minimum),
                // The renewal that makes ONE month cost far more than the other two.
                ob("2026-08-15", "ANNUAL INSURANCE RENEWAL", 90_000, ObligationKind::Recurring),
                ob("2026-09-05", "RENT LANDLORD LLC", 120_000, ObligationKind::Recurring),
                ob("2026-09-12", "NETFLIX.COM", 1_599, ObligationKind::Recurring),
                ob("2026-09-20", "CITY POWER 0412", 9_000, ObligationKind::Recurring),
                ob("2026-09-01", "chase minimum", 6_000, ObligationKind::Minimum),
                ob("2026-09-10", "ZZZ MYSTERY DUES", 4_000, ObligationKind::Recurring),
            ],
        }
    }

    fn cat(category: &'static str, total: i64, typical: i64) -> CategoryTotal {
        CategoryTotal { category, total: usd(total), count: 2, typical_month: usd(typical) }
    }

    fn spending() -> SpendingAnalysis {
        SpendingAnalysis {
            from: "2026-01-01".to_string(),
            to: "2026-06-30".to_string(),
            months_observed: 4,
            outflows: Vec::new(),
            fixed_monthly: usd(0),
            variable_monthly: usd(30_000),
            categories: vec![cat("groceries", 60_000, 15_000), cat("dining", 20_000, 5_000), cat("fuel", 24_000, 6_000), cat("shopping", 16_000, 4_000)],
            variable_categories: vec![cat("groceries", 60_000, 15_000), cat("dining", 20_000, 5_000), cat("fuel", 24_000, 6_000), cat("shopping", 16_000, 4_000)],
            transferred: usd(0),
            transfer_count: 0,
            debt_payments: usd(0),
            uncategorised: vec![
                Txn { account: "chk".into(), date: "2026-05-04".into(), description: "ZZZ".into(), amount: usd(-2_000) },
                Txn { account: "chk".into(), date: "2026-06-04".into(), description: "ZZZ".into(), amount: usd(-3_000) },
            ],
            notes: Vec::new(),
        }
    }

    fn band(month: &str, low: i64) -> MonthBand {
        MonthBand { month: month.to_string(), low: usd(low), expected: usd(low + 50_000), high: usd(low + 100_000) }
    }

    fn projection() -> IncomeProjection {
        IncomeProjection {
            projectable: true,
            reason: None,
            months: vec![band("2026-07", 180_000), band("2026-08", 170_000), band("2026-09", 160_000)],
            total: Some(ProjectionTotal { low: usd(0), expected: usd(0), high: usd(0) }),
            assumptions: Vec::new(),
            excluded: Vec::new(),
            sources_used: 1,
        }
    }

    fn viable(target: i64, with_projection: bool) -> ViableIncome {
        let p = projection();
        minimum_viable_income(&calendar(), &spending(), Currency::USD, if with_projection { Some(&p) } else { None }, &ViableOptions { progress_target: usd(target) })
    }

    #[test]
    fn the_ladder_is_four_tiers_measured_on_the_worst_month() {
        // Every figure measured by running finance-viable.ts on this exact fixture.
        let v = viable(20_000, true);
        let got: Vec<(&str, i64, i64, &str)> = v.tiers.iter().map(|t| (t.tier.label(), t.typical_month.minor, t.worst_month.minor, t.worst_month_name.as_str())).collect();
        assert_eq!(
            got,
            vec![
                ("survival", 160_000, 246_000, "2026-08"),
                ("current", 161_599, 247_599, "2026-08"),
                ("stable", 173_099, 259_099, "2026-08"),
                ("progress", 193_099, 279_099, "2026-08"),
            ]
        );
        assert!(ladder_is_ordered(&v), "each tier costs at least the one below it");
        assert_eq!(v.floor.tier, Tier::Survival);
        // CURRENT is the headline, not survival — survival means letting things lapse, and the
        // consequences of that outlast the month it saved.
        assert_eq!(v.headline.tier, Tier::Current);
    }

    #[test]
    fn the_worst_month_is_the_answer_and_the_gap_to_the_median_is_the_saving_up_problem() {
        let v = viable(20_000, true);
        // August carries the annual renewal: 860.00 more than a usual month. An income clearing the
        // median (161599) covers July and September and MISSES August, which is a missed payment.
        assert_eq!(v.headline.worst_month.minor - v.headline.typical_month.minor, 86_000);
        assert!(v.notes.iter().any(|n| n.contains("2026-08 costs 86000 minor units more than the usual month")));
        assert!(v.notes.iter().any(|n| n.contains("the amount to have put aside before it arrives")));
    }

    #[test]
    fn a_debt_minimum_is_essential_however_it_is_worded() {
        // "chase minimum" matches no category rule, but a missed minimum is a credit event rather
        // than a cancelled luxury — the KIND decides, not the wording.
        assert_eq!(obligation_is_essential("chase minimum", ObligationKind::Minimum), (true, true));
        assert_eq!(obligation_is_essential("anything at all", ObligationKind::Minimum), (true, true));
        // THE CASE THAT ACTUALLY BITES: a minimum whose LABEL categorises as non-essential. Without
        // the kind short-circuit this reads (false, true) and the card would be dropped from the
        // floor — a fixture whose label merely fails to categorise would still pass, because the
        // unplaced fallback promotes it to essential anyway.
        assert_eq!(obligation_is_essential("NETFLIX.COM", ObligationKind::Minimum), (true, true), "a minimum is essential even when its label reads as a luxury");
        assert_eq!(obligation_is_essential("Target RedCard", ObligationKind::Minimum), (true, true), "categorises as `shopping`, and is still a credit event");
        // A subscription is placed and is NOT essential.
        assert_eq!(obligation_is_essential("NETFLIX.COM", ObligationKind::Recurring), (false, true));
        assert_eq!(obligation_is_essential("RENT LANDLORD LLC", ObligationKind::Recurring), (true, true));
    }

    #[test]
    fn an_obligation_nothing_can_place_is_counted_as_essential_and_named() {
        let v = viable(20_000, true);
        // Over-stating a floor costs a bigger target; under-stating it costs a missed payment. The
        // safe direction is chosen AND said out loud rather than quietly applied.
        let note = v.notes.iter().find(|n| n.contains("counted as ESSENTIAL")).expect("the promotion is named");
        assert!(note.contains("ZZZ MYSTERY DUES"));
        assert!(note.contains("under-stating costs you a missed payment"));
    }

    #[test]
    fn the_variable_halves_are_summed_from_the_same_parts_so_the_ladder_cannot_invert() {
        let v = viable(20_000, true);
        // The spending analysis reports 30000 (a median of monthly TOTALS); this builds 32500 from
        // per-category medians plus the uncategorised median. Medians do not add, and using one on
        // each side of the ladder could make the essential half exceed the whole.
        let note = v.notes.iter().find(|n| n.contains("medians do not add")).expect("the discrepancy is stated");
        assert!(note.contains("32500") && note.contains("30000"));
        assert!(ladder_is_ordered(&v));
    }

    #[test]
    fn the_gaps_are_measured_against_the_low_band_in_each_tiers_own_worst_month() {
        let v = viable(20_000, true);
        let gaps = v.gaps.as_ref().expect("a projection was supplied");
        let got: Vec<(&str, i64, bool)> = gaps.iter().map(|g| (g.tier.label(), g.shortfall.minor, g.clears)).collect();
        assert_eq!(got, vec![("survival", 76_000, false), ("current", 77_599, false), ("stable", 89_099, false), ("progress", 109_099, false)]);
        assert!(cleared_tiers(&v).is_empty(), "this income clears none of the ladder");
        assert!(summarise_viable(&v).contains("short by 77599"));
    }

    #[test]
    fn an_income_that_clears_a_tier_says_so() {
        let big = IncomeProjection { months: vec![band("2026-07", 300_000), band("2026-08", 300_000), band("2026-09", 300_000)], ..projection() };
        let v = minimum_viable_income(&calendar(), &spending(), Currency::USD, Some(&big), &ViableOptions { progress_target: usd(20_000) });
        assert_eq!(cleared_tiers(&v), vec![Tier::Survival, Tier::Current, Tier::Stable, Tier::Progress]);
        assert!(summarise_viable(&v).contains("already clears it"));
    }

    #[test]
    fn no_projection_means_the_gaps_are_absent_rather_than_zero() {
        let v = viable(20_000, false);
        // A row of zero shortfalls would read as "you clear every tier", which is the opposite of
        // "nothing was compared".
        assert!(v.gaps.is_none());
        assert!(cleared_tiers(&v).is_empty());
        assert!(!summarise_viable(&v).contains("clears"), "the sentence makes no claim it cannot support");
        // The tiers themselves are unchanged — they do not depend on income.
        assert_eq!(v.headline.worst_month.minor, 247_599);
    }

    #[test]
    fn no_progress_target_collapses_progress_onto_stable_and_says_why() {
        let v = viable(0, true);
        let stable = v.tiers.iter().find(|t| t.tier == Tier::Stable).expect("stable");
        let progress = v.tiers.iter().find(|t| t.tier == Tier::Progress).expect("progress");
        assert_eq!(progress.worst_month.minor, stable.worst_month.minor);
        assert!(v.notes.iter().any(|n| n.contains("a stable position is one where the debt stops growing, not one where it shrinks")));
        assert!(ladder_is_ordered(&v), "equal is still ordered");
    }

    #[test]
    fn each_tier_names_what_it_gives_up() {
        let v = viable(20_000, true);
        let survival = &v.tiers[0];
        assert_eq!(survival.includes.len(), 3);
        assert_eq!(survival.excludes.len(), 3);
        assert!(survival.excludes.iter().any(|e| e.contains("subscription")));
        // Progress gives up nothing — it is the top of the ladder.
        assert!(v.tiers[3].excludes.is_empty());
    }

    #[test]
    fn the_annual_framing_multiplies_the_typical_month_not_the_worst_one() {
        let v = viable(20_000, true);
        // 161599 * 12. The WORST month is what an income must clear; the TYPICAL one is what a year
        // actually costs, and using the worst for both would overstate the year by twelve renewals.
        assert_eq!(over_window(&v, &v.headline, 12).minor, 1_939_188);
        assert_eq!(over_window(&v, &v.headline, 0).minor, 0);
    }
}
